-- Seed script: imports your real August & September data from the spreadsheet.
-- 1. Replace YOUR_EMAIL_HERE below with the email you signed up with.
-- 2. Run this in the Supabase SQL Editor AFTER migration_002_finance.sql and after you've signed up once.

do $$
declare
  v_user_id uuid;
begin
  select id into v_user_id from auth.users where email = 'YOUR_EMAIL_HERE' limit 1;
  if v_user_id is null then
    raise exception 'No user found with that email. Sign up first, then update the email above.';
  end if;

  -- August transactions

  -- September transactions

  -- August budget

  -- September budget

end $$;